h, w = inp.shape

def find_rectangles(grid):
    """Find all maximal rectangles of uniform value"""
    h, w = len(grid), len(grid[0])
    rects = []

    for r1 in range(h):
        for c1 in range(w):
            base_val = grid[r1][c1]
            for r2 in range(r1+2, h+1):
                for c2 in range(c1+3, w+1):
                    height, width = r2-r1, c2-c1
                    count = 0
                    total = height * width

                    for r in range(r1, r2):
                        for c in range(c1, c2):
                            if grid[r][c] == base_val:
                                count += 1

                    if count == total:
                        rects.append((r1, c1, r2, c2, base_val))

    return rects

# Find rectangles in input - looking for large solid rectangles
