import numpy as np
from collections import Counter, deque

demo_input = G['Demo pair 1 input']
h, w = len(demo_input), len(demo_input[0])

def find_4connected_components(grid):
    visited = [[False]*w for _ in range(h)]
    comp_size = [[0]*w for _ in range(h)]
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    for i in range(h):
        for j in range(w):
            if not visited[i][j]:
                queue = deque([(i,j)])
                component = []
                while queue:
                    r, c = queue.popleft()
                    if visited[r][c]: continue
                    visited[r][c] = True
                    component.append((r,c))
                    for dr, dc in directions:
                        nr, nc = r+dr, c+dj
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == grid[r][c]:
                            queue.append((nr, nc))
                size = len(component)
                for r,c in component:
                    comp_size[r][c] = size
    return comp_size

comp_sizes_4 = find_4connected_components(demo_input)

def get_3x3_counts(grid, r, c, H, W):
    counts = {}
    for di in [-1, 0, 1]:
        nr = r+di
        if 0 <= nr < H:
            for dc in [-1, 0, 1]:
                nc = c+dc
                if 0 <= nc < W:
                    val = grid[nr][nc]
                    counts[val] = counts.get(val, 0) + 1
    return counts

# Final rule: Replace isolated cells where orig_count < max_count
result = [row[:] for row in demo_input]
for r in range(h):
    for c in range(w):
        if comp_sizes_4[r][c] == 1:
